/**
 * Generates db/seed.sql from the content schema defaults (= the original landing page copy).
 *   npm run db:seed-sql
 * Seed is idempotent: existing rows are never overwritten (on conflict do nothing).
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { DEFAULT_CONTENT, SECTIONS, sectionFields } from "../src/content/schema";

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const j = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

const lines: string[] = [
  "-- AUTO-GENERATED by scripts/generate-seed.ts — initial content = original landing page.",
  "-- Safe to re-run: existing rows are kept.",
  "begin;",
  "",
  "insert into public.page_sections (id, label, description, sort_order) values",
  SECTIONS.map((s, i) => `  (${q(s.id)}, ${q(s.label)}, ${q(s.description)}, ${i + 1})`).join(",\n"),
  "on conflict (id) do update set label = excluded.label, description = excluded.description, sort_order = excluded.sort_order;",
  "",
  "insert into public.page_content (section_id, field_key, field_type, draft_value, published_value, published_at) values",
];

const rows: string[] = [];
for (const s of SECTIONS) {
  for (const f of sectionFields(s)) {
    const v = DEFAULT_CONTENT[s.id]?.[f.key] ?? null;
    rows.push(`  (${q(s.id)}, ${q(f.key)}, ${q(f.type)}, ${j(v)}, ${j(v)}, now())`);
  }
}
lines.push(rows.join(",\n"), "on conflict (section_id, field_key) do nothing;", "");

lines.push(
  "-- Version 1 = the original landing page, so it can always be restored.",
  "insert into public.content_versions (version_number, snapshot, note, published_by_email)",
  `select 1, ${j(DEFAULT_CONTENT)}, 'Konten awal (landing page original)', 'system'`,
  "where not exists (select 1 from public.content_versions);",
  "",
  "update public.site_status set last_published_at = coalesce(last_published_at, now()),",
  "  last_published_by_email = coalesce(last_published_by_email, 'system'), published_version = coalesce(published_version, 1) where id = 1;",
  "",
  "commit;",
  "",
);

writeFileSync(join(__dirname, "../db/seed.sql"), lines.join("\n"));
console.log(`seed.sql written: ${SECTIONS.length} sections, ${rows.length} fields`);
